namespace geo {
struct Shape {
    virtual ~Shape() {}
    virtual long area() const = 0;
    virtual const char *name() const { return "shape"; }
};
struct Rect : Shape {
    long w, h;
    Rect(long w, long h) : w(w), h(h) {}
    long area() const override { return w * h; }
    const char *name() const override { return "rect"; }
};
struct Square : Rect {
    explicit Square(long s) : Rect(s, s) {}
    const char *name() const override { return "square"; }
};
long total(const Shape *const *shapes, int n) {
    long t = 0;
    for (int i = 0; i < n; i++) t += shapes[i]->area();
    return t;
}
}

use std::env;
use std::hint::black_box;

#[inline(never)]
pub fn pick(scores: &[u32], i: usize) -> u32 {
    scores[i] * 2
}

#[inline(never)]
pub fn checksum(data: &[u8]) -> u32 {
    data.iter().map(|&b| b as u32).sum()
}

fn main() {
    let arg = env::args().nth(1).unwrap_or_else(|| String::from("hello, reverser"));
    let scores = [10u32, 20, 30];
    let i = arg.len() % 4;
    println!("{} {}", checksum(arg.as_bytes()), pick(black_box(&scores), black_box(i)));
}

