// ListFuncs.java: count functions and how many lack a real name.
import ghidra.app.script.GhidraScript;
import ghidra.program.model.listing.*;

public class ListFuncs extends GhidraScript {
    @Override
    public void run() throws Exception {
        int total = 0, unnamed = 0;
        for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
            total++;
            if (f.getName().startsWith("FUN_")) unnamed++;
        }
        println("functions=" + total + " unnamed(FUN_)=" + unnamed);
    }
}

